import {initialLocalLift,localLiftOwner,localLiftCollisionLines} from './local-lift-physics.js';
import {spatialIndex,querySpatial} from './spatial-index.js';
import {beginLift,chooseLift,cancelLift,tickLift,liftFloors} from './lift.js';
import {tickPortals,portalsClosed,portalsReady} from './portal-state.js';
import {doorLeaf} from './doors.js';
import {Biology} from './biology.js';
import {toWorld,toLocal,worldLine,worldRect,radians} from './pose.js';
import {Automation} from './automation.js';
import {slideCandidates} from './contact-slide.js';
import {jointGeometry,FLOOR_THICKNESS,JOINT_WALL} from './joint-geometry.js';
import {Experience,NPCS} from './experience.js';
import {BODIES,BY_ID,RADIUS,NEXT,DEFAULT_EXPERIMENT,SIZES,METHODS,LEVELS,WALK_SPEED,RUN_SPEED,placements,connections,reachable,serviceReachable,portStates,regionAt,insideBody,boundaryWalls,portalJambs,portSegment,segmentDistance,LANDING,POINTS,extendLocalLiftReach} from './architecture.js';
import {planTransfer,validatePlan,positionDuring} from './transport.js';
export const CABIN={x:-6.55,z:2.05,w:3.9,d:3.9};
export function fixedWalls(){return[{a:[LANDING.x,2.06],b:[-.4,2.06]},{a:[LANDING.x,5.94],b:[-.4,5.94]},{a:[-2.34,2],b:[-2.34,2.4]},{a:[-2.34,5.6],b:[-2.34,6]},{a:[-.46,2],b:[-.46,3]},{a:[-.46,5],b:[-.46,6]}];}
export class Simulation{
 constructor(e=DEFAULT_EXPERIMENT){this.reset(e);}
 reset(e=this.experiment??DEFAULT_EXPERIMENT){this.experiment={...DEFAULT_EXPERIMENT,...e};if(!SIZES[this.experiment.size]||!METHODS[this.experiment.method])throw Error('Unknown experiment');this.phase='A';this.positions=placements('A',this.experiment);this.player={x:-1.2,y:LEVELS[1],z:4,yaw:Math.PI/2,pitch:0,owner:'F1'};this.doors=Object.fromEntries(BODIES.flatMap(b=>b.doors.map(d=>[d.id,d.open])));this.mode='idle';this.elapsed=0;this.plan=null;this.stageIndex=-1;this.paused=false;this.speed=2;this.experimental=false;this.shutter=0;this.passenger=null;this.evacuationActive=false;this.liftY=LEVELS[1];this.liftTarget=this.liftY;this.liftFrom=this.liftY;this.liftTime=0;this.liftActive=false;this.liftPassenger=false;this.liftState='open';this.liftGate=0;this.localLift=initialLocalLift();this.message='第三層の住戸から、南北に分岐する通路を探索できます。';this.history=[];this.lastCheck=null;this.completed=0;this.clock=0;this.experience=new Experience(this);this.automation=new Automation(this);this.warningDuration=5;this.biology=new Biology(this);this.invalidate();this.portalAmounts={};tickPortals(this,0,true);}
 get levels(){return LEVELS;}
 get next(){return NEXT[this.phase];}
 invalidate(){this._ownersIndex=null;this._colliders=null;this._links=null;this._ports=null;this._joints=null;this._reach=null;this._targetReach=null;}
 get liveConnections(){return this._links??=connections(this.phase,this.experiment,this.doors).map(c=>this.shutter>.01&&!c.permanent?{...c,status:'blocked'}:c);}
 get livePorts(){return this._ports??=portStates(this.phase,this.experiment,this.doors).map(p=>this.shutter>.01&&!p.permanent?{...p,status:'blocked',openings:[],masked:[{a:p.a,b:p.b}]}:p);}
 get joints(){return this._joints??=this.liveConnections.filter(c=>c.status!=='blocked').map(c=>({...c.bridge,id:c.id,height:c.height,status:c.status,permanent:c.permanent,a:c.a,b:c.b}));}
 get bridges(){return this.joints;}
 get liveReachable(){if(this._reach)return this._reach;const seen=new Set(LEVELS.map((_,i)=>`F${i}`));let changed=true;while(changed){changed=extendLocalLiftReach(seen);for(const c of this.liveConnections.filter(c=>c.status==='pass')){if(seen.has(c.a)&&!seen.has(c.b)){seen.add(c.b);changed=true;}if(seen.has(c.b)&&!seen.has(c.a)){seen.add(c.a);changed=true;}}}return this._reach=seen;}
 get safetyDoors(){return Object.fromEntries(Object.keys(this.doors).map(k=>[k,k!=='R3-door']));}
 get safetyRegion(){return this.safetyRegionAtPoint(this.player.x,this.player.z,this.player.y);}
 safetyRegionAtPoint(x,z,y=this.player.y){const id=this.ownerAt(x,z,y);if(!BY_ID[id])return id;const q=toLocal(this.positions[id],{x,z});return regionAt(id,q.x,q.z,this.safetyDoors);}
 get targetReachable(){return this._targetReach??=serviceReachable(this.next,this.experiment,this.safetyDoors);}
 get targetRiskRegions(){return new Set([...serviceReachable(this.phase,this.experiment,this.safetyDoors)].filter(n=>n.includes('/')&&!this.targetReachable.has(n)));}
 get targetIsolated(){return[...new Set([...this.targetRiskRegions].map(n=>n.split('/')[0]))];}
 portIsOpen(id,p){const q=this.livePorts.find(q=>q.key===`${id}:${p.id}`);return!!q&&q.status!=='blocked';}
 get anyLiftActive(){return this.liftActive||this.localLift.liftActive;}
 isLiftOwner(owner=this.owner){return owner==='lift'||owner==='local-lift';}
 get currentLift(){const owner=this.owner;return this.localLift.liftActive||owner==='local-lift'||String(owner??'').startsWith('LF')?this.localLift:this;}
 get owner(){return this.ownerAt(this.player.x,this.player.z,this.player.y);}
 get ownerRegion(){return this.regionAtPoint(this.player.x,this.player.z,this.player.y);}
 ownerCandidates(x,z,y){if(!this._ownersIndex)this._ownersIndex=spatialIndex(BODIES,b=>{const f={w:(Math.max(...b.cells.map(c=>c[0]))+1)*8,d:(Math.max(...b.cells.map(c=>c[1]))+1)*8};return worldRect(this.positions[b.id],{x:0,z:0,...f});},b=>this.positions[b.id].y);return querySpatial(this._ownersIndex,x,z,y);}
 ownerAt(x,z,y=this.player.y){const local=localLiftOwner(this,x,z,y,CABIN);if(local)return local;if(x>=CABIN.x&&x<=CABIN.x+CABIN.w&&z>=CABIN.z&&z<=CABIN.z+CABIN.d&&Math.abs(y-this.liftY)<.01)return'lift';for(const b of this.physicsIndex===false?BODIES:this.ownerCandidates(x,z,y)){const p=this.positions[b.id];const q=toLocal(p,{x,z});if(Math.abs(p.y-y)<.01&&insideBody(b,q.x,q.z))return b.id;}const l=LEVELS.findIndex(q=>Math.abs(q-y)<.01);if(l>=0&&x>=LANDING.x&&x<=-.4&&z>=2&&z<=6)return`F${l}`;if(l>=0&&x>=-2.65&&x<=-2.4&&z>=2.4&&z<=5.6)return`F${l}`;for(const q of this.joints)if(Math.abs(q.y-y)<.01&&x>=q.x&&x<=q.x+q.w&&z>=q.z&&z<=q.z+q.d)return`joint:${q.id}`;return null;}
 regionAtPoint(x,z,y=this.player.y){const id=this.ownerAt(x,z,y);if(BY_ID[id]){const q=toLocal(this.positions[id],{x,z});return regionAt(id,q.x,q.z,this.doors);}return id;}
 floorSupports(x,z,y){return!!this.ownerAt(x,z,y);}
 colliders(){if(this._colliders)return this._colliders;const lines=[],solids=[],add=(l,owner,y,p={x:0,z:0,y:0})=>lines.push({...worldLine(p,l),owner,y});
  for(let i=0;i<LEVELS.length;i++){const y=LEVELS[i];for(const l of fixedWalls())add(l,`F${i}`,y);if(this.liftGate>.001||Math.abs(this.liftY-y)>.01)add({a:[-2.5,2.4],b:[-2.5,5.6]},`F${i}`,y);const p=this.livePorts.find(p=>p.key===`F${i}:E`);for(const m of p?.masked??[{a:1,b:3}])add({a:[-.46,LANDING.z+m.a],b:[-.46,LANDING.z+m.b]},`F${i}`,y);}
  for(const l of[{a:[CABIN.x+.06,CABIN.z],b:[CABIN.x+.06,CABIN.z+CABIN.d]},{a:[CABIN.x,CABIN.z+.06],b:[CABIN.x+CABIN.w,CABIN.z+.06]},{a:[CABIN.x,CABIN.z+CABIN.d-.06],b:[CABIN.x+CABIN.w,CABIN.z+CABIN.d-.06]},{a:[-2.71,2.05],b:[-2.71,2.4]},{a:[-2.71,5.6],b:[-2.71,5.95]}])add(l,'lift',this.liftY);if(this.liftGate>.001)add({a:[-2.71,2.4],b:[-2.71,5.6]},'lift',this.liftY);
  lines.push(...localLiftCollisionLines(this,CABIN,fixedWalls));
  for(const b of BODIES){const q=this.positions[b.id];for(const l of[...boundaryWalls(b),...b.walls,...b.doors.flatMap(d=>{const t=this.doors[d.id]?1:this.experience.doorProgress[d.id];return !this.doors[d.id]&&t>.001?[d,doorLeaf(d,t)]:[doorLeaf(d,t)];}),...b.ports.flatMap(p=>portalJambs(b,p))])add(l,b.id,q.y,q);for(const p of b.ports){const state=this.livePorts.find(s=>s.key===`${b.id}:${p.id}`);for(const m of state?.masked??[{a:p.a,b:p.b}])add(portSegment(b,{...p,...m},p.adaptive?.5:.2),b.id,q.y,q);for(const o of state?.openings??[])if(o.height<2)add(portSegment(b,{...p,a:o.a,b:o.b},p.adaptive?.5:.2),b.id,q.y,q);}for(const n of NPCS.filter(n=>n.body===b.id))solids.push({...worldRect(q,{x:n.x-n.radius,z:n.z-n.radius,w:n.radius*2,d:n.radius*2}),y:q.y,owner:b.id});for(const s of[...b.solids,...b.furniture])solids.push({...worldRect(q,s),y:q.y,owner:b.id});}
  for(const source of this.joints){const {sides}=jointGeometry(source);const j=source;for(const l of sides)add(l,'joint',j.y);}return this._colliders={lines,solids,lineIndex:spatialIndex(lines,l=>({x:Math.min(l.a[0],l.b[0]),z:Math.min(l.a[1],l.b[1]),w:Math.abs(l.b[0]-l.a[0]),d:Math.abs(l.b[1]-l.a[1])}),l=>l.y),solidIndex:spatialIndex(solids,s=>s,s=>s.y)};
 }
 isFree(x,z,y=this.player.y,radius=RADIUS){if(!this.floorSupports(x,z,y))return false;for(let i=0;i<16;i++){const a=i*Math.PI/8;if(!this.floorSupports(x+Math.cos(a)*radius,z+Math.sin(a)*radius,y))return false;}const c=this.colliders();for(const l of this.physicsIndex===false?c.lines:querySpatial(c.lineIndex,x,z,y,radius+.06))if(Math.abs(l.y-y)<.01&&segmentDistance(x,z,l.a,l.b)<radius+.06-1e-7)return false;for(const s of this.physicsIndex===false?c.solids:querySpatial(c.solidIndex,x,z,y,radius+.06))if(Math.abs(s.y-y)<.01&&Math.hypot(Math.max(s.x-x,0,x-s.x-s.w),Math.max(s.z-z,0,z-s.z-s.d))<radius+.01)return false;return true;}
 move(dx,dz){if(this.experience.visit)return false;if(!['idle','warning','evacuate','auto-evacuate'].includes(this.mode)||this.anyLiftActive)return false;let moved=false;const steps=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.08));for(let i=0;i<steps;i++)for(const[ax,az]of[[dx/steps,0],[0,dz/steps]]){if(Math.abs(ax)+Math.abs(az)<1e-12)continue;const x=this.player.x+ax,z=this.player.z+az,owner=this.ownerAt(x,z),region=this.safetyRegionAtPoint(x,z);if(['warning','evacuate'].includes(this.mode)&&!this.automation.exceptions.has(this.regionAtPoint(x,z))&&BY_ID[owner]&&!this.targetReachable.has(region)&&this.safetyRegion!==region&&!this.evacuationActive){this.message='閉鎖予定の内部通路への新規入場を制限中です。';continue;}if(this.isFree(x,z)){this.player.x=x;this.player.z=z;moved=true;if(this.targetReachable.has(region))this.evacuationActive=false;}else{for(const c of slideCandidates(this.player,ax,az,this.colliders().lines)){const xx=this.player.x+c.x,zz=this.player.z+c.z,r=this.safetyRegionAtPoint(xx,zz);if(['warning','evacuate'].includes(this.mode)&&!this.automation.exceptions.has(this.regionAtPoint(xx,zz))&&!this.evacuationActive&&!this.targetReachable.has(r))continue;if(this.isFree(xx,zz)){this.player.x=xx;this.player.z=zz;moved=true;break;}}}}this.player.owner=this.owner;return moved;}
 walk(forward,side,dt,run=false){if(this.experience.blocking){if(forward<0)this.experience.leave();return false;}const n=Math.hypot(forward,side)||1,d=dt*(run?RUN_SPEED:WALK_SPEED),yaw=this.player.yaw;return this.move((Math.sin(yaw)*forward-Math.cos(yaw)*side)/n*d,(Math.cos(yaw)*forward+Math.sin(yaw)*side)/n*d);}
 startTransfer(){if(this.mode!=='idle'||this.anyLiftActive)return false;this.plan=planTransfer(this.phase,this.next,this.experiment);this.lastCheck=validatePlan(this.plan,this.positions);if(!this.lastCheck.ok){this.message=`搬送不成立：${this.plan.planningError??this.lastCheck.errors[0]?.type}`;return false;}this.mode='warning';this.elapsed=0;this.paused=false;this.evacuationActive=!this.targetReachable.has(this.safetyRegion)||this.owner?.startsWith('joint:');this.message=`搬送警告。閉鎖予定の通路：${this.targetIsolated.join('・')||'なし'}。継手から離れてください。`;return this.automation.prepare();}
 cancelWarning(){if(['warning','evacuate'].includes(this.mode)){this.mode='idle';this.plan=null;this.elapsed=0;this.message='搬送準備を取り消しました。';}}
 beginClosing(){if(this.automation.begin())return;const own=this.owner;if(!this.automation.allowed()&&BY_ID[own]&&!this.targetReachable.has(this.safetyRegion)){this.mode='evacuate';this.message='退避待ち：この内部通路は次周期で到達不能になります。安全な通路へ歩いて退避してください。';return;}let seam=!own||own.startsWith('joint:');for(let i=0;i<16&&!seam;i++){const a=i*Math.PI/8;if(this.ownerAt(this.player.x+Math.cos(a)*.46,this.player.z+Math.sin(a)*.46)!==own)seam=true;}if(seam){this.mode='evacuate';this.message='格納する接合トンネルをまたいでいます。区画の内側へ移動してください。';return;}this.passenger=BY_ID[own]?{id:own,...toLocal(this.positions[own],this.player),yaw:this.player.yaw+radians(this.positions[own])}:null;this.mode=this.biology.retracted?'closing':'retracting';this.elapsed=0;this.invalidate();}
 tick(dt){this.clock+=dt;if(this.paused)return;this.experience.tick(dt);this.biology.tick(dt);tickPortals(this,dt);this.automation.tick(dt);if(this.mode==='auto-evacuate')return;const delta=Math.min(.1,dt)*this.speed;tickLift(this,dt);if(this.mode==='idle')return;if(this.mode==='retracting'){if(this.biology.retracted){this.mode='closing';this.elapsed=0;}return;}if(this.mode==='evacuate'){this.beginClosing();return;}this.elapsed+=delta;if(this.mode==='warning'){if(this.elapsed>=this.warningDuration&&this.automation.warningReal>=this.automation.reactionSeconds)this.beginClosing();return;}if(this.mode==='closing'){this.shutter=Math.min(1,this.elapsed/1.2);this.invalidate();if(this.elapsed>=1.5&&this.biology.retracted&&portalsClosed(this)){this.mode='moving';this.elapsed=0;this.shutter=1;}return;}
  if(this.mode==='moving'){this.positions=positionDuring(this.plan,Math.min(this.elapsed,this.plan.duration));let sum=0;this.stageIndex=this.plan.stages.findIndex(s=>{sum+=s.duration;return this.elapsed<sum;});if(this.passenger){const p=this.positions[this.passenger.id];const q=toWorld(p,this.passenger);this.player.x=q.x;this.player.z=q.z;this.player.y=p.y;this.player.yaw=this.passenger.yaw-radians(p);}this.invalidate();if(this.elapsed>=this.plan.duration){this.phase=this.plan.to;this.mode='opening';this.elapsed=0;this.completed++;this.experience.event('dock',this.owner);this.history.unshift(`${this.plan.from}→${this.phase}：${this.lastCheck.checks}連続検査・離隔違反0`);this.history=this.history.slice(0,6);}return;}
  if(this.mode==='opening'){this.shutter=1-Math.min(1,this.elapsed/1.2);this.invalidate();if(this.elapsed>=1.3&&portalsReady(this)){this.mode='idle';this.shutter=0;this.invalidate();this.message=BY_ID[this.owner]&&!this.liveReachable.has(this.ownerRegion)?this.owner==='C0'?'予備廊下の保管状態です。Bで再挿入されます。':'意図的な孤立状態です。次のAで再接続できます。':'搬送完了。近道・環状路・開口ごとの変化を探索できます。';}}
 }
 useLift(){return beginLift(this);}
 chooseLift(y){return chooseLift(this,y);}
 cancelLift(){return cancelLift(this);}
 get liftFloors(){return liftFloors(this);}
 interact(){if(this.biology.interact())return;if(this.experience.interact())return;if(!['idle','warning','evacuate'].includes(this.mode))return;if(this.isLiftOwner()||/^L?F\d+$/.test(this.owner??'')){this.useLift();return;}let near=null,dist=1.7;for(const b of BODIES){const p=this.positions[b.id];if(Math.abs(p.y-this.player.y)>.01)continue;for(const d of b.doors){const n=segmentDistance(toLocal(p,this.player).x,toLocal(p,this.player).z,d.a,d.b);if(n<dist){near=d;dist=n;}}}if(!near){this.message='E：近くの通常扉、または固定EVを操作。';return;}const b=BODIES.find(b=>b.doors.includes(near));this.experience.toggleDoor(b,near);}

 rescue(){this.experience.leave();this.experience.end();this.experience.blend=0;this.experience.focus=null;this.player={x:-1.2,y:LEVELS[1],z:4,yaw:Math.PI/2,pitch:0,owner:'F1'};this.passenger=null;for(const c of [this,this.localLift])if(c.liftActive){c.liftActive=false;c.liftPassenger=false;c.liftY=c.liftTarget;c.liftState='open';c.liftGate=0;}this.invalidate();this.message='デバッグ復帰：固定EV乗場へ移動。通常の物理的出口には含めません。';}
 referencePoint(name){const p=POINTS[name],q=this.positions[p.body];return toWorld(q,p);}
}
